/* ---------- reward / punish ---------- */
.split{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--rule);border:1px solid var(--rule);margin:var(--sp-3) 0}
@media(max-width:44rem){.split{grid-template-columns:1fr}}
.split > div{background:var(--surface);padding:var(--sp-3)}
.split ul{margin:0;padding-left:1.05rem;display:flex;flex-direction:column;gap:.4rem;font-size:var(--fs-sm)}
.split .up li::marker{content:"+ ";font-family:var(--mono);color:var(--accent)}
.split .down li::marker{content:"− ";font-family:var(--mono);color:var(--ink-3)}
