.split .up li::before{content:"+";position:absolute;left:0;font-family:var(--mono);color:var(--accent);font-weight:600}
.split .down li::before{content:"−";position:absolute;left:0;font-family:var(--mono);color:var(--ink-3);font-weight:600}

/* ---------- timetable ---------- */
.tt{border-top:1px solid var(--rule-strong);margin:var(--sp-3) 0}
