.tt-row.pivot .tt-time{color:var(--accent-ink)}
.tt-row.rest .tt-body b,.tt-row.rest .tt-time{color:var(--ink-3)}

/* ---------- checklist ---------- */
.checks{display:grid;grid-template-columns:repeat(auto-fit,minmax(17rem,1fr));gap:var(--sp-2) var(--sp-4);margin:var(--sp-3) 0;list-style:none;padding:0}
.checks li{position:relative;padding-left:1.6rem;font-size:var(--fs-sm);border-bottom:1px solid var(--rule);padding-bottom:var(--sp-2)}
