.pitch ol li::marker{font-family:var(--mono);color:var(--ink-3)}

.quotes{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--rule);border:1px solid var(--rule);margin:var(--sp-3) 0}
@media(max-width:44rem){.quotes{grid-template-columns:1fr}}
.quotes > div{background:var(--surface);padding:var(--sp-3)}
