# --- per-ref -------------------------------------------------------------------

def _ingest_ref(reader: "_BlobReader", ref: str, links: dict,
                repo_slug: str) -> list[dict]:
    """One Battle per session dir under every checkpoint root in `ref`."""
    paths = set(_git(reader.repo, "ls-tree", "-r", "--name-only", ref).splitlines())
    battles = []
    for root in _checkpoint_roots(paths):
        top_meta = _read_json(reader, ref, root + "metadata.json")
        for n in _session_dirs(paths, root):
            try:
                battles.append(
                    _battle_from_session(reader, ref, root, n, top_meta,
                                         links, repo_slug))
            except Exception as exc:
                print(f"[ingest_entire] skipping {ref}:{root}{n}/: {exc}",
                      file=sys.stderr)
    return battles


def _checkpoint_roots(paths: set) -> list[str]:
    """Prefixes that look like a checkpoint: own metadata.json + a 0/ session."""
    meta_dirs = {p[: -len("metadata.json")] for p in paths
                 if p.endswith("metadata.json")}
    return sorted(r for r in meta_dirs if r + "0/metadata.json" in paths)


def _session_dirs(paths: set, root: str) -> list[int]:
    """Session dir numbers (0, 1, ...) under a checkpoint root."""
    ns = []
    for p in paths:
        if p.startswith(root) and p.endswith("/metadata.json"):
            rest = p[len(root):-len("/metadata.json")]
            if rest.isdigit():
                ns.append(int(rest))
    return sorted(ns)


